// A luminous shrine frames the exit portal.
const gate=new THREE.Group();gate.position.set(10,.12,5.6);scene.add(gate);const gateMat=new THREE.MeshStandardMaterial({color:'#ff9ccf',emissive:'#ff3b9c',emissiveIntensity:2,metalness:.5,roughness:.22});
const ring=new THREE.Mesh(new THREE.TorusGeometry(.58,.075,10,36),gateMat);ring.position.y=.95;gate.add(ring);const portal=new THREE.Mesh(new THREE.CircleGeometry(.48,32),new THREE.MeshBasicMaterial({color:'#d94ba7',transparent:true,opacity:.32,side:THREE.DoubleSide}));portal.position.set(0,.95,0);portal.rotation.y=.35;gate.add(portal);cylinder(.48,.58,.2,mats.dark,10,.18,5.6);
