function makeCharacter(id,color,enemy=false){const root=new THREE.Group(), rig=new THREE.Group();root.add(rig);const glow=mat(color,.35,.15,color), skin=mat(enemy?'#e6b5d4':'#f5d6c9'), hair=mat(enemy?'#512746':id==='kira'?'#9c455d':id==='yuki'?'#45417e':'#433557'), cloth=mat(enemy?'#642d66':id==='kira'?'#b84d59':id==='yuki'?'#534b9b':'#397c93',.48,.08), trim=mat('#f2d284',.3,.55);
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.3,20),new THREE.MeshBasicMaterial({color:'#20192c',transparent:true,opacity:.32}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;root.add(shadow);
 const body=new THREE.Group();body.position.y=.62;rig.add(body);const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.22,.38,4,8),cloth);torso.castShadow=true;body.add(torso);const sash=box(.08,.47,.25,trim,0,.01,.205,body);sash.rotation.z=-.22;
 const head=new THREE.Group();head.position.y=.43;body.add(head);const face=sphere(.19,skin,0,.05,0,head);const haircap=sphere(.2,hair,0,.14,-.045,head);haircap.scale.set(1,.68,1);const fringe=new THREE.Mesh(new THREE.ConeGeometry(.12,.3,5),hair);fringe.position.set(-.12,.02,.08);fringe.rotation.z=.55;head.add(fringe);sphere(.025,mat('#563d60'),-.065,.045,.174,head);sphere(.025,mat('#563d60'),.065,.045,.174,head);
 const limbs=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.115,-.24,0);body.add(leg);cylinder(.085,.105,.36,cloth,0,-.13,0,leg,8);box(.15,.09,.23,mat('#272640'),0,-.32,.04,leg);limbs.push({part:leg,kind:'leg',side});const arm=new THREE.Group();arm.position.set(side*.25,.2,0);body.add(arm);cylinder(.075,.085,.33,cloth,0,-.13,0,arm,8);sphere(.09,skin,0,-.3,.015,arm);limbs.push({part:arm,kind:'arm',side});}
 // Distinctive weapon silhouettes make each guardian readable in motion.
 if(!enemy){if(id==='mira'){const bow=new THREE.Mesh(new THREE.TorusGeometry(.19,.035,7,18,Math.PI),glow);bow.position.set(.34,.1,.13);bow.rotation.z=-Math.PI/2;body.add(bow);const arrow=cylinder(.018,.018,.55,trim,.34,.1,.12,body,6);arrow.rotation.z=Math.PI/2;}else if(id==='kira'){const orb=sphere(.14,glow,.34,.12,.08,body);const staff=cylinder(.035,.045,.8,trim,.34,-.03,.04,body,8);staff.rotation.z=-.13;sphere(.09,glow,.34,.38,.04,body)}else{const blade=new THREE.Mesh(new THREE.ConeGeometry(.075,.68,5),glow);blade.position.set(.32,.08,.08);blade.rotation.z=-Math.PI/2;body.add(blade);}}
 else {for(const side of [-1,1]){const horn=new THREE.Mesh(new THREE.ConeGeometry(.07,.25,5),glow);horn.position.set(side*.14,.25,-.03);horn.rotation.z=-side*.35;head.add(horn)}}
 return{root,rig,body,head,limbs,glow,phase:Math.random()*6,attack:0,hit:0};}

