import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js';
const $=s=>document.querySelector(s), canvas=$('#game');
const units=[{id:'mira',name:'Mira',role:'Star Archer',emoji:'🏹',cost:90,color:'#8eeaff',range:2.9,damage:16,rate:.82,desc:'Long range · balanced',stats:'RANGE 3 · ATK 16'},{id:'kira',name:'Kira',role:'Flame Mage',emoji:'🔥',cost:125,color:'#ff9d87',range:2.25,damage:33,rate:1.35,desc:'Splash · heavy burst',stats:'RANGE 2 · ATK 33'},{id:'yuki',name:'Yuki',role:'Frost Guard',emoji:'❄️',cost:105,color:'#b7a5ff',range:2.4,damage:11,rate:.5,slow:true,desc:'Rapid · slows enemies',stats:'RANGE 2 · SLOWS'}];
const stages=[{name:'Moonlit Pass',desc:'The first rift has opened. Hold the line, Starwarden.',chapter:'01 · THE MOONLIT PASS'},{name:'Sakura Crossing',desc:'A crimson tide spills through the shrine gates.',chapter:'02 · SAKURA CROSSING'},{name:'Celestial Ruins',desc:'Ancient stars awaken beneath the broken spires.',chapter:'03 · CELESTIAL RUINS'}];
const route=[[0,5.6],[2.5,5.6],[2.5,3.8],[5.3,3.8],[5.3,2],[8,2],[8,5.6],[10,5.6]], slots=[[1,4.55],[3.55,5.05],[3.5,3.15],[6.25,3.05],[6.25,1.35],[8.8,2.85],[8.85,5.05]];
const state={gold:260,lives:20,stage:0,wave:0,mode:'story',selected:null,towers:[],enemies:[],shots:[],particles:[],running:false,spawn:0,toSpawn:0,spawnTimer:0,elapsed:0,speed:1,gameOver:false};
const scene=new THREE.Scene();scene.background=new THREE.Color('#777d9f');scene.fog=new THREE.Fog('#777d9f',19,38);
const camera=new THREE.PerspectiveCamera(34,1,.1,100);camera.position.set(5,12.2,15);camera.lookAt(5,.1,3.8);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight('#dceaff','#4c426d',1.65));const sun=new THREE.DirectionalLight('#fff0d6',2.5);sun.position.set(-5,12,7);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-12;sun.shadow.camera.right=12;sun.shadow.camera.top=12;sun.shadow.camera.bottom=-12;scene.add(sun);
const mat=(color,roughness=.65,metalness=0,emissive=null)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive:emissive||'#000000',emissiveIntensity:emissive?1.5:0});
const mats={grass:mat('#536b69'),edge:mat('#384358'),road:mat('#9a836f'),road2:mat('#c5a98b'),gold:mat('#ffd985',.3,.55),white:mat('#fff4df'),dark:mat('#302d48'),leaf:mat('#4b9b89'),pink:mat('#fa85c0',.32,.1,'#ec499e'),cyan:mat('#74eaff',.28,.2,'#38dfff'),violet:mat('#b89aff',.3,.2,'#9b69ff')};
const ground=new THREE.Mesh(new THREE.BoxGeometry(11,1,8),mats.edge);ground.position.set(5,-.52,3.8);ground.receiveShadow=true;scene.add(ground);
const top=new THREE.Mesh(new THREE.BoxGeometry(10.85,.18,7.85),mats.grass);top.position.set(5,-.02,3.8);top.receiveShadow=true;scene.add(top);
function box(w,h,d,material,x,y,z,parent=scene){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function sphere(r,material,x,y,z,parent){const o=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),material);o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o}
